import triton
import triton.language as tl

@triton.jit
def cholesky_kernel(A_ptr, L_ptr, n, stride, upper, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(0)
    # Calculate the starting index for this block
    row_start = pid * BLOCK_SIZE
    col_start = 0

    # Load the block of A
    A = tl.zeros((BLOCK_SIZE, BLOCK_SIZE), dtype=tl.float32)
    for i in range(BLOCK_SIZE):
        for j in range(BLOCK_SIZE):
            if row_start + i < n and col_start + j < n:
                A[i, j] = tl.load(A_ptr + (row_start + i) * stride + (col_start + j))

    # Perform Cholesky decomposition on the block
    for k in range(BLOCK_SIZE):
        if row_start + k < n:
            A[k, k] = tl.sqrt(A[k, k])
            for i in range(k + 1, BLOCK_SIZE):
                if row_start + i < n:
                    A[i, k] = A[i, k] / A[k, k]
            for j in range(k + 1, BLOCK_SIZE):
                for i in range(j, BLOCK_SIZE):
                    if row_start + i < n:
                        A[i, j] = A[i, j] - A[i, k] * A[j, k]

    # Store the result in L
    for i in range(BLOCK_SIZE):
        for j in range(BLOCK_SIZE):
            if row_start + i < n and col_start + j < n:
                if upper:
                    if j >= i:
                        tl.store(L_ptr + (row_start + i) * stride + (col_start + j), A[i, j])
                else:
                    if i >= j:
                        tl.store(L_ptr + (row_start + i) * stride + (col_start + j), A[i, j])
